/**
 * V0 Project Detector
 *
 * Detects if a project was generated by Vercel V0 based on:
 * - Next.js framework
 * - shadcn/ui component library
 * - Tailwind CSS styling
 * - React Server Components patterns
 *
 * Extends BaseDetector for common functionality
 */

import path from 'path';
import { BaseDetector } from './base-detector.js';

export class V0Detector extends BaseDetector {
  priority = 3; // Higher priority than Figma Make (priority 4)
  tool = 'v0';

  /**
   * Detect V0 projects with comprehensive analysis
   *
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<{tool: string|null, confidence: number, evidence: string[], metadata: Object}>}
   */
  async detect(projectRoot) {
    const evidence = [];
    let confidence = 0.0;

    // Check package.json for Next.js and V0 signatures
    const pkgConfidence = await this.checkPackageJson(projectRoot);
    confidence += pkgConfidence.score;
    evidence.push(...pkgConfidence.evidence);

    // Check component structure for V0 patterns
    const structConfidence = await this.checkComponentStructure(projectRoot);
    confidence += structConfidence.score;
    evidence.push(...structConfidence.evidence);

    // Check configuration files
    const configConfidence = await this.checkConfigurations(projectRoot);
    confidence += configConfidence.score;
    evidence.push(...configConfidence.evidence);

    // Check import patterns in components
    const importConfidence = await this.checkImportPatterns(projectRoot);
    confidence += importConfidence.score;
    evidence.push(...importConfidence.evidence);

    // Normalize confidence to 0-1 range
    // Maximum achievable confidence is ~4.0 across all checks
    const normalizedConfidence = Math.min(confidence / 4.0, 1.0);

    return {
      tool: normalizedConfidence > 0.5 ? 'v0' : null,
      confidence: normalizedConfidence,
      evidence,
      metadata: {
        framework: 'nextjs',
        buildTool: 'nextjs-build',
        componentLibrary: 'shadcn/ui',
        styling: 'tailwindcss'
      }
    };
  }

  /**
   * Check package.json for V0-related dependencies
   *
   * @private
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<{score: number, evidence: string[]}>}
   */
  async checkPackageJson(projectRoot) {
    const evidence = [];
    let score = 0;

    const pkg = await this.readPackageJson(projectRoot);
    if (!pkg) {
      return { score: 0, evidence: ['package.json not found'] };
    }

    // Check for Next.js (strongest V0 indicator)
    if (pkg.dependencies?.next) {
      score += 0.6;
      evidence.push(`Next.js v${pkg.dependencies.next} detected`);
    }

    // Check for shadcn/ui dependencies (strong V0 indicator)
    const shadcnDeps = [
      '@radix-ui/react-dialog',
      '@radix-ui/react-dropdown-menu',
      '@radix-ui/react-select',
      '@radix-ui/react-label',
      '@radix-ui/react-slot',
      'lucide-react',
      'tailwindcss-animate',
      'class-variance-authority'
    ];

    const foundShadcnDeps = shadcnDeps.filter(dep => pkg.dependencies?.[dep]);

    if (foundShadcnDeps.length >= 4) {
      score += 0.8;
      evidence.push(`shadcn/ui dependencies detected (${foundShadcnDeps.length} packages)`);
    } else if (foundShadcnDeps.length >= 2) {
      score += 0.4;
      evidence.push(`Some shadcn/ui dependencies detected (${foundShadcnDeps.length} packages)`);
    }

    // Check for Tailwind CSS
    if (pkg.devDependencies?.tailwindcss || pkg.dependencies?.tailwindcss) {
      score += 0.3;
      evidence.push('Tailwind CSS configured');
    }

    // Check for clsx + tailwind-merge (V0 utility pattern)
    if (pkg.dependencies?.clsx && pkg.dependencies?.['tailwind-merge']) {
      score += 0.2;
      evidence.push('clsx + tailwind-merge utility pattern detected');
    }

    // Check for React 18+ (typical of V0)
    if (pkg.dependencies?.react) {
      const majorVersion = parseInt(pkg.dependencies.react.match(/\d+/)?.[0] || '0');
      if (majorVersion >= 18) {
        score += 0.1;
        evidence.push(`React v${pkg.dependencies.react} (18+ typical for V0)`);
      }
    }

    return { score: Math.min(score, 1.0), evidence };
  }

  /**
   * Check for V0 component structure patterns
   *
   * @private
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<{score: number, evidence: string[]}>}
   */
  async checkComponentStructure(projectRoot) {
    const evidence = [];
    let score = 0;

    // Check for /components/ui directory (shadcn/ui pattern)
    const uiDir = path.join(projectRoot, 'components', 'ui');
    const hasUiDir = await this.dirExists(uiDir);

    if (hasUiDir) {
      const uiFiles = await this.listFiles(uiDir);
      const tsxFiles = uiFiles.filter(f => f.endsWith('.tsx') || f.endsWith('.ts'));

      if (tsxFiles.length > 0) {
        score += 0.8;
        evidence.push(`shadcn/ui components directory found (${tsxFiles.length} components)`);
      }
    }

    // Check for kebab-case component naming
    const componentsDir = path.join(projectRoot, 'components');
    const hasComponents = await this.dirExists(componentsDir);

    if (hasComponents) {
      const files = await this.listFiles(componentsDir);
      const kebabFiles = files.filter(f =>
        /^[a-z][a-z0-9]*(-[a-z0-9]+)*\.(tsx|ts)$/.test(f)
      );

      if (kebabFiles.length >= 3) {
        score += 0.4;
        evidence.push(`kebab-case component naming detected (${kebabFiles.length} files)`);
      }
    }

    // Check for Next.js App Router
    const appDir = path.join(projectRoot, 'app');
    const hasAppRouter = await this.dirExists(appDir);

    if (hasAppRouter) {
      score += 0.3;
      evidence.push('Next.js App Router directory found');
    }

    return { score: Math.min(score, 1.0), evidence };
  }

  /**
   * Check for V0 configuration files
   *
   * @private
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<{score: number, evidence: string[]}>}
   */
  async checkConfigurations(projectRoot) {
    const evidence = [];
    let score = 0;

    // Check for components.json (shadcn/ui CLI config)
    const componentsJsonPath = path.join(projectRoot, 'components.json');
    const hasComponentsJson = await this.fileExists(componentsJsonPath);

    if (hasComponentsJson) {
      score += 0.9;
      evidence.push('components.json found (shadcn/ui CLI configuration)');

      try {
        const content = await this.readFile(componentsJsonPath);
        const json = JSON.parse(content);
        if (json.$schema?.includes('shadcn')) {
          evidence.push('Valid shadcn/ui configuration schema detected');
        }
      } catch (error) {
        // JSON parse error
      }
    }

    // Check for tailwind.config.ts
    const tailwindPath = path.join(projectRoot, 'tailwind.config.ts');
    const hasTailwind = await this.fileExists(tailwindPath);

    if (hasTailwind) {
      score += 0.3;
      evidence.push('tailwind.config.ts found');
    }

    // Check tsconfig.json for path aliases
    const tsconfigPath = path.join(projectRoot, 'tsconfig.json');
    const hasTsconfig = await this.fileExists(tsconfigPath);

    if (hasTsconfig) {
      try {
        const content = await this.readFile(tsconfigPath);
        const tsconfig = JSON.parse(content);

        if (tsconfig.compilerOptions?.paths?.['@/*']) {
          score += 0.2;
          evidence.push('Path aliases (@/) configured (V0/Next.js pattern)');
        }
      } catch (error) {
        // JSON parse error
      }
    }

    return { score: Math.min(score, 1.0), evidence };
  }

  /**
   * Check for V0 import patterns in components
   *
   * @private
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<{score: number, evidence: string[]}>}
   */
  async checkImportPatterns(projectRoot) {
    const evidence = [];
    let score = 0;

    const patterns = [
      {
        regex: /from ["']lucide-react["']/,
        name: 'Lucide React icons',
        weight: 0.3
      },
      {
        regex: /from ["']@\/components\/ui\//,
        name: 'shadcn/ui component imports',
        weight: 0.8
      },
      {
        regex: /^["']use client["']/m,
        name: 'React Server Components ("use client")',
        weight: 0.5
      },
      {
        regex: /from ["']next\/link["']/,
        name: 'Next.js Link component',
        weight: 0.2
      },
      {
        regex: /from ["']next\/image["']/,
        name: 'Next.js Image component',
        weight: 0.2
      }
    ];

    const componentsDir = path.join(projectRoot, 'components');
    const foundPatterns = new Set();

    try {
      const files = await this.getAllSourceFiles(componentsDir);

      for (const file of files.slice(0, 15)) {
        const content = await this.readFile(file);
        if (!content) continue;

        for (const { regex, name, weight } of patterns) {
          if (regex.test(content) && !foundPatterns.has(name)) {
            score += weight;
            foundPatterns.add(name);
            evidence.push(`${name} pattern detected in components`);
          }
        }
      }
    } catch (error) {
      // Components directory doesn't exist or is inaccessible
    }

    return { score: Math.min(score, 1.0), evidence };
  }
}

export default V0Detector;
